 "intro": [
  "这是一款慢生活沙盒：你扮成人形的百变怪（<i class='jp'>Ditto</i>），给荒废的关都盖房子、造栖息地、把宝可梦请回来。它几乎没有永久错过的东西，最难的不是操作，而是不知道下一步要什么材料、某只宝可梦要什么栖息地。",
  "所以这页按「下一个门槛 → 要备什么 → 卡住看什么」排流程，再配一份能搜的图鉴：搜宝可梦名看它的栖息地、时间和天气，搜栖息地名看配方和可遇对象。真正有时限的只有活动，以黄框标出。",
  "专名说明：宝可梦、招式、城镇、栖息地、道具与特长一律采用官方简中名（与神奇宝贝百科记录一致）；正文里的外文原名用灰字保留，方便和外文资料对照。图鉴为便于搜索只列中文。游戏内用词可能因版本略有差异，以游戏内文字为准。"
 ],
