    "修好健身区休息处见快拳郎（<i class='jp'>Hitmonchan</i>），用 2 个石头换碎岩（<i class='jp'>Rock Smash</i>），打通西边。墙后的大岩蛇（<i class='jp'>Onix</i>）要放到后面再救。路上可以先认识飘飘球（<i class='jp'>Drifloon</i>），它之后负责梦岛。",
    "用海浪边的草丛请呆呆兽（<i class='jp'>Slowpoke</i>），引它到宝可梦中心，接 <b>用哈欠来降雨吧！</b>。",
