    "遇到球球海狮（<i class='jp'>Popplio</i>），从沙地开口潜下去。升到高级才能开门（要扩展票），把这里的环境等级升到 3。",
    "接 <b>「建造美丽建筑吧！」</b>：50 星斑岩、30 石头、25 贝壳、10 闪亮珍珠、10 贝壳栅栏、2 海洋门 + 15 只宝可梦。",
    "龙虾小兵（<i class='jp'>Corphish</i>）：用满是沙的海底草丛招来后，拿潜水艇套组，造巨牙鲨潜水艇。",
    "太阳珊瑚（<i class='jp'>Corsola</i>）：用海底珊瑚的草丛招来，再请水跃鱼（<i class='jp'>Mudkip</i>）修田、利牙鱼（<i class='jp'>Carvanha</i>）切西瓜。",
    "好坏星（<i class='jp'>Mareanie</i>）：用珊瑚的摇曳花田招来，拿闪亮珍珠做海洋风沙发。",
    "小锯鳄（<i class='jp'>Totodile</i>）：陪玩后用灯笼鱼（<i class='jp'>Chinchou</i>）给泡泡机通电。泥泥鳅（<i class='jp'>Barboach</i>）：从暗谷取回贝壳座椅，搭海中休息处。轻飘飘（<i class='jp'>Frillish</i>）：带探宝机进洞，砸开发光方块找宝石海星玩偶。",
    "闪亮珍珠：把洞里的脏珍珠交给有擦亮特长的刺甲贝（<i class='jp'>Cloyster</i>）或巨牙鲨（<i class='jp'>Sharpedo</i>）。贝壳栅栏配方在电脑商店；海洋门配方埋在工地下面。",
    "清掉工地的沙和海底方块，派六只伙伴加另外 8 只，和球球海狮一起开工，等 1 小时。进神殿见玛纳霏，主线结束。"
