 "qa": [
  {
   "q": "门打不开 / 下一步不触发？",
   "a": "区域门同时看主线进度和训练家等级。先做完头顶黄气泡和图鉴委托里的委托，再盖房子、提环境等级。还不行就问博士。"
  },
  {
   "q": "环境等级升不上去？",
   "a": "让这里的宝可梦更舒服：住进合适的家、添家具、完成委托。重建宝可梦中心、盖建筑也能加分，传说和幻之宝可梦的加成更大。"
  },
  {
   "q": "想要某只宝可梦但一直不来？",
   "a": "到「图鉴」搜它的名字，核对栖息地、城镇、时间和天气，然后过一段时间再回来看。稀有度低的可能要多等几次。"
  },
  {
   "q": "纸哪里来？",
   "a": "把废纸交给有 <b>回收利用</b> 特长的宝可梦。梦岛的快龙玩偶也偏向产废纸。"
  },
  {
   "q": "砖块哪里来？",
   "a": "把软黏土交给有 <b>点火</b> 特长的宝可梦（暗沉沉海边的城镇的火稚鸡就行）。"
  },
  {
   "q": "绒毛哪里来？",
   "a": "到青绵鸟、咩利羊这类宝可梦的家附近捡。有 <b>乱撒</b> 特长的宝可梦会在家附近掉材料。"
  },
  {
   "q": "硬石头、铁链、铁丝网弄不开？",
   "a": "这些要强化招式：面包强化居合斩，牛排强化碎岩。先救出藏饱栗厨才能开始做。"
  },
  {
   "q": "电不够？",
   "a": "小型发电机 5、风力发电机 10（高处 20）、水力发电机 20、熔炉 30（要续燃料）。用电线杆接线，普通距离约 10 格。"
  },
  {
   "q": "雷公、炎帝、水君、超梦怎么一直找不到？",
   "a": "它们在梦岛有概率出现，玩偶只是提高概率，不保证。岛每天重置一次，当天没有就第二天再去。"
  },
  {
   "q": "活动过期了怎么办？",
   "a": "Serebii 只记录了档期，跳绳活动办过两次，其他活动是否复刻未知。The Games Wiki 提到可以改主机时钟进入，但这不是官方玩法，后续也可能被修。"
  }
 ],
 "tips": [
  {
   "t": "环境等级与解锁",
   "a": "每个城镇有独立等级（1–10）。升级会解锁电脑挑战和商店物品，等级 5 送道具、等级 10 送配方。"
  },
  {
   "t": "梦岛怎么用",
   "a": "和飘飘球交朋友后可去，每天一次。玩偶决定偏向：皮卡丘 → 线团 / 海玻璃碎片 / 贝壳；伊布 → 苹野果 / 藤绳 / 发光蘑菇；皮皮 → 洞窟蘑菇 / 铜 / 石灰石；风速狗 → 铁 / 金 / 发光石；快龙 → 废纸 / 宝可金属 / 水晶；宝石海星 → 海葡萄 / 小珊瑚 / 脏珍珠。留在岛上的东西带不回来。"
  },
  {
   "t": "料理强化",
   "a": "沙拉强化树叶（长苔藓和水草）；面包强化居合斩；牛排强化碎岩；汤强化水枪（出水更多）；冰沙强化冲浪（水下也能当拉普拉斯，还能碎岩）。"
  },
  {
   "t": "喂苔卡比兽",
   "a": "按菜的主味道获得效果，到游戏内次日 05:00 结束。苦：更容易出稀有物；涩：更容易见到洛奇亚、凤王；酸：商店更好且打折；辣：栖息地更容易来宝可梦；甜：更容易出古代遗物。"
  },
  {
   "t": "电磁飘浮是建造神技",
   "a": "通关后的电磁飘浮能自由飞，还能一次放最多 9 个方块，可切换横竖和替换方块，每次使用消耗 PP。"
  },
  {
   "t": "宝可梦中心能做什么",
   "a": "每座中心每天能恢复一次 PP。3D 打印：拍照后切参考模式（Y），在打印机复制物品，消耗宝可金属或稀有宝可金属。"
  },
  {
   "t": "友谊与玩小游戏",
   "a": "完成委托、送礼、陪玩都加友谊。看那边三局两胜，赢了加得更多。友谊到高位后宝可梦会偶尔送材料。"
  },
  {
   "t": "水与岩浆",
   "a": "普通水会产生闪亮涟漪，海水不会。泥水和岩浆不增湿；用水枪把岩浆变成黑石。"
  },
  {
   "t": "空空镇的三个大工程",
   "a": "穿过干巴巴荒野的城镇的桥就到。这里是自由建造区，也是联机地图。双子冰窖、无人发电厂、火光祭坛各需 15 只宝可梦，对应三神鸟。"
  },
  {
   "t": "梦幻的石板",
   "a": "随机发光地面能挖到神秘石板，共 27 种。带探宝机和有找东西特长的宝可梦更容易找到。"
  }
 ],
